parameters.jsCode:
const payload = $json.body ?? $json;
const pr = payload.pull_request ?? {};

if (payload.action !== 'closed' || pr.merged !== true) {
  return [];
}

const branch = String(pr.head?.ref ?? '');
if (!branch.startsWith('codex/')) {
  return [];
}

const sources = [pr.body, pr.title, branch].filter(Boolean).map(String);
let jiraKey = '';
for (const source of sources) {
  const marker = source.match(/codex-jira-key:\s*([A-Z][A-Z0-9]+-\d+)/i);
  const fallback = source.match(/\b([A-Z][A-Z0-9]+-\d+)\b/i);
  jiraKey = (marker?.[1] ?? fallback?.[1] ?? '').toUpperCase();
  if (jiraKey) break;
}

if (!jiraKey) {
  throw new Error(`Merged PR #${pr.number ?? 'unknown'} is not linked to Jira`);
}

return [{ json: {
  jiraKey,
  prNumber: Number(pr.number),
  prUrl: String(pr.html_url ?? ''),
  branch,
  mergedBy: String(pr.merged_by?.login ?? payload.sender?.login ?? 'unknown'),
  mergeCommitSha: String(pr.merge_commit_sha ?? '')
} }];

const transitions = $input.all();
const normalize = (value) => String(value ?? '').trim().toLowerCase().replace(/[^a-z0-9а-яё]/g, '');
const aliases = String($env.JIRA_DONE_NAMES ?? 'Done,Complete,Completed,Closed,Resolved,Готово,Выполнено,Завершено,Закрыто').split(',').map(normalize).filter(Boolean);
const target = transitions.find((item) => item.json.to?.statusCategory?.key === 'done')
  ?? transitions.find((item) => aliases.includes(normalize(item.json.name)) || aliases.includes(normalize(item.json.to?.name)));

if (!target) {
  const available = transitions.map((item) => `${item.json.id}: ${item.json.name ?? 'unnamed'} -> ${item.json.to?.name ?? 'unknown'} [category ${item.json.to?.statusCategory?.key ?? 'unknown'}]`).join(', ');
  throw new Error(`Jira Done transition is not available. Configured aliases: ${aliases.join(', ') || 'none'}. Add and publish a transition from the issue's current status to a Done-category status. Available transitions: ${available || 'none'}`);
}

return [{ json: { transitionId: String(target.json.id), targetStatusName: String(target.json.to?.name ?? target.json.name ?? 'Done') } }];

